Great! We've achieved a 25% speedup with shared memory. Now let's try to optimize further with loop unrolling.

### Iteration 3: Loop Unrolling
I'll add loop unrolling to reduce branching and improve instruction-level parallelism. I'll also use register variables to minimize memory access.

```python
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;
    int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;

    for (int tile = 0; tile < num_tiles; tile += UNROLL_FACTOR) {
        // Preload multiple tiles
        for (int i = 0; i < UNROLL_FACTOR; i++) {
            int t = tile + i;
            if (t < num_tiles) {
                int tile_col = t * TILE_SIZE + threadIdx.x;
                int tile_row = t * TILE_SIZE + threadIdx.y;

                // Load A tile
                if (row < N && tile_col < N) {
                    As[threadIdx.y][threadIdx.x] = A[row * N + tile_col];
                } else {
                    As[threadIdx.y][threadIdx.x] = 0.0f;
                }

                // Load B tile
                if (tile_row < N && col < N) {
                    Bs[threadIdx.y][threadIdx.x] = B[tile_row * N + col];
                } else {
                    Bs[threadIdx.y][threadIdx.x] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute with unrolled tiles
        for (int i = 0; i < UNROLL_FACTOR; i++) {
            int t = tile + i;
            if (t < num_tiles) {
                for (int k = 0; k < TILE_SIZE; k++) {
                    sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
                }
            }
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 threads(TILE_SIZE, TILE_SIZE);
    dim3 blocks((N + TILE_SIZE - 1) / TILE_SIZE, 
                (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<blocks, threads>>>(A.data_ptr<float>(), 
                                       B.data_ptr<float>(), 
                                       C.data_ptr<float>(), 
                                       N);

    return C;
}
"""

cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

matmul_ext = load_inline(
    name="matmul_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
