### Iteration 4: Optimized Shared Memory with Bank Conflict Avoidance
I'll implement a kernel that uses shared memory more efficiently by transposing one of the matrices to avoid bank conflicts. I'll also use larger tile sizes and better thread utilization.

```python
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define THREADS_PER_BLOCK 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float c_val = 0.0f;

    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load A tile
        int load_row = row;
        int load_col = tile * TILE_SIZE + tx;
        if (load_row < N && load_col < N) {
            As[ty][tx] = A[load_row * N + load_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load B tile (transposed)
        int b_row = tile * TILE_SIZE + ty;
        int b_col = col;
        if (b_row < N && b_col < N) {
            Bs[tx][ty] = B[b_row * N + b_col];  // Transposed store
        } else {
            Bs[tx][ty] = 0.0f;
        }

        __syncthreads();

        // Compute dot product
        for (int k = 0; k < TILE_SIZE; k++) {
            c_val += As[ty][k] * Bs[tx][k];  // Coalesced access
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = c_val;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
